function pixelExplosion(p,t,duration,x,y,size,seed=0,alpha=1){if(t<0||t>duration)return;const age=t/duration,expand=Math.min(1,age*3.5),fade=Math.min(1,(1-age)*3);p.save();p.globalAlpha=alpha*fade;const pixel=Math.max(2,Math.round(size/32));const disc=(cx,cy,r,color)=>{p.fillStyle=color;for(let yy=-r;yy<=r;yy+=pixel){const ww=Math.floor(Math.sqrt(Math.max(0,r*r-yy*yy))/pixel)*pixel;if(ww>0)p.fillRect(Math.round((cx-ww)/pixel)*pixel,Math.round((cy+yy)/pixel)*pixel,ww*2,pixel);}};const n=6+seed%4;for(let k=0;k<n;k++){const angle=k*Math.PI*2/n+seed*.37,r=size*(.07+.13*expand),cx=x+Math.cos(angle)*size*.22*expand,cy=y+Math.sin(angle)*size*.16*expand-age*size*.08;disc(cx,cy,r,age>.6?'#75635e':'#a94728');disc(cx-pixel,cy-pixel,r*.72,age>.6?'#a08b77':'#ee7b24');if(age<.65)disc(cx-pixel*2,cy-pixel*2,r*.42,'#ffdb75');}if(age<.38)disc(x,y,size*.17*(1-age),'#fff4b4');p.restore();}
